const crypto = require("crypto");
const {
  questionIdentity,
  questionFields,
  normalizeQuestionFields,
  questionDraftText,
} = require("./question-draft-contract");

/** Live authority stays in this host. Disk records are editable recovery data. */
class QuestionDrafts {
  constructor({ store, getConversation, post, refresh }) {
    Object.assign(this, { store, getConversation, post, refresh });
    this.requests = new Map();
  }

  register(conv, request) {
    let digest, fields, recoveryError;
    try {
      digest = questionIdentity(conv.sessionId, request);
      fields = questionFields(request);
      if (fields.length > 128)
        throw new Error("Question has more than 128 draft fields");
    } catch (error) {
      recoveryError = error.message;
      digest = crypto.randomBytes(32).toString("hex");
      fields = [];
    }
    for (const entry of this.requests.values()) {
      if (
        entry.conv === conv &&
        entry.request.id === request.id &&
        entry.state !== "archived"
      ) {
        if (entry.digest === digest && this.live(entry)) return entry.request;
        this.archive(entry, "Question replaced");
      }
    }
    // Only archived instances may be evicted. Never silently lose a live request.
    if (this.requests.size >= 256) {
      const old = [...this.requests.values()].find(
        (r) => r.state === "archived",
      );
      if (old) this.requests.delete(old.instance);
      else throw new Error("Too many pending questions");
    }
    const instance = crypto.randomUUID();
    const entry = {
      conv,
      session: conv.session,
      token: conv._sessionToken,
      key: conv.draftKey,
      sessionId: conv.sessionId || "",
      instance,
      recordId: instance,
      digest,
      fields,
      state: "draft",
      revision: -1,
      recoveryError,
    };
    entry.request = {
      ...request,
      convId: conv.id,
      draftKey: entry.key,
      questionInstance: instance,
      questionKey: digest,
      draftFields: fields,
      draftStorage: !!this.store && !recoveryError,
      questionState: "draft",
      ...(recoveryError ? { recoveryError } : {}),
    };
    this.requests.set(instance, entry);
    return entry.request;
  }

  match(message) {
    const r = this.requests.get(message.questionInstance);
    return r &&
      r.conv.id === message.convId &&
      r.key === message.draftKey &&
      r.digest === message.questionKey &&
      r.request.id === message.id
      ? r
      : null;
  }

  live(r) {
    return (
      r.state !== "archived" &&
      this.getConversation(r.conv.id) === r.conv &&
      r.conv.session === r.session &&
      r.conv._sessionToken === r.token &&
      r.conv.draftKey === r.key &&
      (r.conv.sessionId || "") === r.sessionId
    );
  }

  message(r, kind, extra = {}) {
    this.post({
      kind,
      convId: r.conv.id,
      draftKey: r.key,
      id: r.request.id,
      questionInstance: r.instance,
      questionKey: r.digest,
      ...extra,
    });
  }

  async load(r) {
    if (!this.store || r.recoveryError) return [];
    if (!r.loading)
      r.loading = (async () => {
        const saved = await this.store.view(r.key, { includeComposer: false });
        const binding = r.request.binding;
        // Legacy unbound requests can only recover in the original live instance.
        const bound =
          binding?.sessionId === r.sessionId &&
          typeof binding?.turnId === "string" &&
          binding.turnId &&
          typeof binding?.toolUseId === "string" &&
          binding.toolUseId &&
          Number.isSafeInteger(binding?.sequence);
        const prior = saved.questions.find(
          (q) =>
            q.digest === r.digest &&
            q.sessionId === r.sessionId &&
            q.requestId === r.request.id &&
            q.status === "draft" &&
            (q.id === r.recordId || bound),
        );
        if (prior && this.live(r) && r.revision < 0) {
          r.recordId = prior.id;
          r.values = normalizeQuestionFields(r.fields, prior.fields);
        }
        return r.values || [];
      })().catch((error) => {
        r.loading = null;
        throw error;
      });
    await r.loading;
    return r.values || [];
  }

  async restore(message) {
    const r = this.match(message);
    if (!r || !this.live(r)) return;
    try {
      const values = await this.load(r);
      if (this.live(r))
        this.message(r, "questionDraftSnapshot", {
          fields: values,
          state: r.state,
        });
    } catch (error) {
      this.message(r, "questionDraftError", { text: error.message });
    }
  }

  async save(message) {
    const r = this.match(message);
    if (!r || !this.store || r.recoveryError) return;
    const values = normalizeQuestionFields(r.fields, message.fields || []);
    if (!Number.isSafeInteger(message.revision) || message.revision < 0)
      throw new Error("Invalid question draft revision");
    await this.load(r);
    r.revision++;
    r.values = values;
    await this.store.saveQuestion(r.key, {
      id: r.recordId,
      digest: r.digest,
      sessionId: r.sessionId,
      requestId: r.request.id,
      title: String(r.request.question || "Question").slice(0, 1024),
      fields: values,
      text: questionDraftText(r.fields, values),
      status: r.state === "draft" && this.live(r) ? "draft" : "archived",
    });
  }

  archive(r, reason) {
    if (r.state === "archived") return;
    r.state = "archived";
    r.request.questionState = "archived";
    this.message(r, "questionState", { state: "archived", text: reason });
    if (this.store)
      this.store
        .archiveQuestion(r.key, r.recordId, r.digest)
        .then(() => this.refresh(r.conv))
        .catch((error) =>
          this.message(r, "questionDraftError", { text: error.message }),
        );
  }

  rejected(conv, id, reason) {
    for (const r of this.requests.values()) {
      if (
        r.conv !== conv ||
        r.request.id !== id ||
        !this.live(r) ||
        !["saving", "pending"].includes(r.state)
      )
        continue;
      r.state = "unknown";
      r.request.questionState = "unknown";
      this.message(r, "questionState", {
        state: "unknown",
        text:
          "Agent rejected the response: " +
          String(reason || "unknown reason").slice(0, 256) +
          ". Saved text remains available.",
      });
    }
  }

  archiveConversation(
    conv,
    {
      blockingOnly = false,
      id = null,
      reason = "Question closed; saved text remains editable",
    } = {},
  ) {
    for (const r of this.requests.values())
      if (
        r.conv === conv &&
        (!id || r.request.id === id) &&
        (!blockingOnly || r.request.blocking !== false)
      )
        this.archive(r, reason);
  }

  async answer(message, openUrl) {
    const r = this.match(message);
    if (!r || !this.live(r) || r.state !== "draft" || !r.session?.running)
      return;
    // Reserve before the first await. A second click must never dispatch again.
    r.state = "saving";
    r.request.questionState = "saving";
    this.message(r, "questionState", {
      state: "saving",
      text: "Saving answer…",
    });
    try {
      await this.save(message);
    } catch (error) {
      if (this.live(r)) {
        r.state = "draft";
        r.request.questionState = "draft";
        this.message(r, "questionState", {
          state: "draft",
          text: `Answer was not sent: ${error.message}`,
        });
      }
      return;
    }
    if (!this.live(r) || r.state !== "saving") return;
    let answer = message.answer === undefined ? null : message.answer;
    if (openUrl) {
      // Use the reviewed host-owned URL, never a URL supplied by the Webview.
      try {
        const target = new URL(r.request.url);
        if (
          r.request.mode !== "url" ||
          !r.request.elicitation ||
          target.protocol !== "https:" ||
          !target.hostname ||
          target.username ||
          target.password
        )
          throw new Error("unsafe URL");
        answer = (await openUrl(target.href)) === false ? null : {};
      } catch {
        answer = null;
      }
      if (!this.live(r) || r.state !== "saving") return;
    }
    r.state = "pending";
    r.request.questionState = "pending";
    try {
      const sent = r.session.sendEvent({
        type: "answer",
        id: r.request.id,
        answer,
        ...(r.request.binding ? { binding: r.request.binding } : {}),
      });
      if (sent === false) throw new Error("Agent pipe unavailable");
      if (this.live(r) && r.state === "pending")
        this.message(r, "questionState", {
          state: "pending",
          text: "Submitted; waiting for agent confirmation",
        });
    } catch {
      if (this.live(r)) {
        r.state = "unknown";
        r.request.questionState = "unknown";
        this.message(r, "questionState", {
          state: "unknown",
          text: "Delivery is unknown. Saved text is available; no automatic retry.",
        });
      }
    }
    this.refresh(r.conv);
  }
}
module.exports = { QuestionDrafts };

import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import { Window } from "happy-dom";
import { DraftStore } from "../../../vscode-extension/src/chat/draft-store.js";
import { QuestionDrafts } from "../../../vscode-extension/src/chat/question-drafts.js";
import {
  questionIdentity,
  questionFields,
  normalizeQuestionFields,
} from "../../../vscode-extension/src/chat/question-draft-contract.js";
import { ChatViewProvider } from "../../../vscode-extension/src/chat/chat-view.js";
import { buildChatHtml } from "../../../vscode-extension/src/chat/chat-html.js";

const cleanups = [];
afterEach(async () => {
  for (const fn of cleanups.splice(0).reverse()) await fn();
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-question-"));
  cleanups.push(() => fs.rm(root, { recursive: true, force: true }));
  return root;
}
const binding = {
  backgroundAgentId: null,
  sessionId: "session-1",
  turnId: "turn-1",
  toolUseId: "tool-1",
  sequence: 1,
};
const request = {
  kind: "question",
  id: "q1",
  question: "Choose a target",
  binding,
};
const values = [{ key: "answer", value: "half entered 中文" }];
const payload = (q, extra = {}) => ({
  ...q,
  fields: values,
  revision: 1,
  ...extra,
});
function controller(store, overrides = {}) {
  cleanups.push(async () => {
    let queue;
    do {
      queue = store.queue;
      await queue;
    } while (queue !== store.queue);
  });
  const conv = {
    id: "a",
    sessionId: "session-1",
    draftKey: randomUUID(),
    _sessionToken: {},
    session: { running: true, sendEvent: vi.fn(() => true) },
    ...overrides,
  };
  const messages = [];
  const drafts = new QuestionDrafts({
    store,
    getConversation: (id) => (id === conv.id ? conv : null),
    post: (m) => messages.push(m),
    refresh: () => {},
  });
  return { drafts, conv, messages };
}
function ui(backup = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  cleanups.push(() => window.happyDOM.abort());
  const sent = [];
  let state = backup;
  window.acquireVsCodeApi = () => ({
    postMessage: (m) => sent.push(m),
    getState: () => state,
    setState: (v) => {
      state = v;
    },
  });
  window.document.write(
    buildChatHtml({ nonce: "n", cspSource: "vscode-resource:" }),
  );
  const emit = (data) =>
    window.dispatchEvent(new window.MessageEvent("message", { data }));
  const card = (q) => window.document.getElementById("q-" + q.questionInstance);
  return { window, sent, emit, card, state: () => state };
}

describe("question recovery authority and persistence", () => {
  it("recovers an unfinished bound question in a fresh host without sending an answer", async () => {
    const root = await storage();
    const first = controller(new DraftStore(root));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), {
      draftKey: first.conv.draftKey,
    });
    const restored = next.drafts.register(next.conv, request);
    expect(restored.questionInstance).not.toBe(q.questionInstance);
    await next.drafts.restore(restored);
    expect(next.messages.at(-1)).toMatchObject({
      kind: "questionDraftSnapshot",
      fields: values,
      state: "draft",
    });
    expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    await next.drafts.save(
      payload(restored, { fields: [{ key: "answer", value: "finished" }] }),
    );
    expect(
      (await next.drafts.store.view(first.conv.draftKey)).questions,
    ).toHaveLength(1);
  });

  it("archives cancellations, schema changes and late edits without reviving the request", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.save(payload(q));
    const changed = h.drafts.register(h.conv, {
      ...request,
      options: ["a", "b"],
    });
    await h.drafts.save(
      payload(q, { fields: [{ key: "answer", value: "late text" }] }),
    );
    await h.drafts.answer(payload(q, { answer: "stale" }));
    await h.drafts.restore(changed);
    expect(h.messages.at(-1).fields).toEqual([]);
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0],
    ).toMatchObject({ status: "archived", text: "Answer: late text" });
  });

  it("does not restore unbound or already submitted answers as a new live form", async () => {
    const root = await storage();
    for (const bound of [false, true]) {
      const h = controller(new DraftStore(root));
      const original = { ...request, binding: bound ? binding : undefined };
      const q = h.drafts.register(h.conv, original);
      await h.drafts.save(payload(q));
      if (bound) await h.drafts.answer(payload(q, { answer: "sent" }));
      const next = controller(new DraftStore(root), {
        draftKey: h.conv.draftKey,
      });
      const nextQ = next.drafts.register(next.conv, original);
      await next.drafts.restore(nextQ);
      expect(next.messages.at(-1).fields).toEqual([]);
      expect(
        (await next.drafts.store.view(h.conv.draftKey)).questions[0].text,
      ).toContain("half entered");
      expect(next.conv.session.sendEvent).not.toHaveBeenCalled();
    }
  });

  it("reserves one response, persists before writing, and leaves failed delivery unknown", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    h.conv.session.sendEvent.mockReturnValue(false);
    await Promise.all([
      h.drafts.answer(payload(q, { answer: "x" })),
      h.drafts.answer(payload(q, { answer: "x" })),
    ]);
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
    expect(h.messages.at(-1)).toMatchObject({ state: "unknown" });
    expect(
      (await h.drafts.store.view(h.conv.draftKey)).questions[0].status,
    ).toBe("archived");
    await h.drafts.answer(payload(q, { answer: "retry" }));
    expect(h.conv.session.sendEvent).toHaveBeenCalledOnce();
  });

  it("does not dispatch on storage failure or a reset during the save", async () => {
    const h = controller(new DraftStore(await storage()));
    const q = h.drafts.register(h.conv, request);
    await h.drafts.restore(q);
    const save = vi
      .spyOn(h.drafts.store, "saveQuestion")
      .mockRejectedValueOnce(new Error("disk full"));
    await h.drafts.answer(payload(q, { answer: "x" }));
    expect(h.messages.at(-1)).toMatchObject({
      state: "draft",
      text: "Answer was not sent: disk full",
    });
    save.mockRestore();
    let release;
    const original = h.drafts.store.saveQuestion.bind(h.drafts.store);
    vi.spyOn(h.drafts.store, "saveQuestion").mockImplementation(
      async (...args) => {
        await new Promise((resolve) => {
          release = resolve;
        });
        return original(...args);
      },
    );
    const sending = h.drafts.answer(payload(q, { answer: "x" }));
    await vi.waitFor(() => expect(release).toBeTypeOf("function"));
    h.conv._sessionToken = {};
    release();
    await sending;
    expect(h.conv.session.sendEvent).not.toHaveBeenCalled();
  });

  it("keeps deferred questions across turn end and bounds stored questions", async () => {
    const h = controller(new DraftStore(await storage()));
    const blocking = h.drafts.register(h.conv, request);
    const deferred = h.drafts.register(h.conv, {
      ...request,
      id: "later",
      blocking: false,
    });
    await h.drafts.save(payload(blocking));
    await h.drafts.save(payload(deferred));
    h.drafts.archiveConversation(h.conv, { blockingOnly: true });
    expect(h.drafts.match(deferred).state).toBe("draft");
    expect(h.drafts.match(blocking).state).toBe("archived");
    for (let i = 2; i < 16; i++)
      await h.drafts.save(
        payload(h.drafts.register(h.conv, { ...request, id: "q" + i })),
      );
    await expect(
      h.drafts.save(
        payload(h.drafts.register(h.conv, { ...request, id: "overflow" })),
      ),
    ).rejects.toThrow("16 questions");
    expect((await h.drafts.store.list())[0].label).toBe(request.question);
  });
});

