    send.click();
    send.click();
    expect(view.sent.filter((m) => m.type === "answer")).toHaveLength(1);
    expect(card.classList.contains("done")).toBe(false);
    await h.drafts.answer(view.sent.find((m) => m.type === "answer"));
    view.emit(h.messages.at(-1));
