import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import path from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";
import { QuestionDrafts } from "../src/chat/question-drafts.js";
import { DraftStore } from "../src/chat/draft-store.js";

const cleanups = [];
afterEach(async () => {
  for (const fn of cleanups.splice(0).reverse()) await fn();
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-reload-"));
  cleanups.push(() => fs.rm(root, { recursive: true, force: true }));
  return root;
}

const binding = {
  backgroundAgentId: null,
  sessionId: "session-1",
  turnId: "turn-1",
  toolUseId: "tool-1",
  sequence: 1,
};
const request = {
  kind: "question",
  id: "q1",
  question: "Choose a target",
  binding,
};
const values = [{ key: "answer", value: "half entered" }];
const payload = (q, extra = {}) => ({
  ...q,
  fields: values,
  revision: 1,
  ...extra,
});

function makeConv(sessionId, draftKey) {
  return {
    id: "a",
    sessionId,
    draftKey,
    _sessionToken: {},
    session: { running: true, sendEvent: vi.fn(() => true) },
  };
}
function controller(store, conv) {
  const messages = [];
  const drafts = new QuestionDrafts({
    store,
    getConversation: (id) => (id === conv.id ? conv : null),
    post: (m) => messages.push(m),
    refresh: () => {},
  });
  return { drafts, conv, messages };
}
function snapshots(messages) {
  return messages.filter((m) => m.kind === "questionDraftSnapshot");
}

describe("reload question binding (verify-27)", () => {
  it("restores live fields only on an exact re-dispatch", async () => {
    const root = await storage();
    const key = randomUUID();
    const first = controller(new DraftStore(root), makeConv("session-1", key));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), makeConv("session-1", key));
    const restored = next.drafts.register(next.conv, request);
    await next.drafts.restore(restored);
    expect(snapshots(next.messages).at(-1)).toMatchObject({
      fields: values,
      state: "draft",
    });
  });

  it("does not restore live fields when the schema (digest) differs", async () => {
    const root = await storage();
    const key = randomUUID();
    const first = controller(new DraftStore(root), makeConv("session-1", key));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), makeConv("session-1", key));
    // Only the schema changes (a single-select is added); id/session/binding
    // stay identical so digest mismatch is the sole changed condition.
    const changed = next.drafts.register(next.conv, {
      ...request,
      options: ["alpha", "beta"],
    });
    await next.drafts.restore(changed);
    expect(snapshots(next.messages).at(-1).fields).toEqual([]);
    expect(snapshots(next.messages).at(-1).state).toBe("draft");
  });

  it("does not restore live fields when the session differs", async () => {
    const root = await storage();
    const key = randomUUID();
    const first = controller(new DraftStore(root), makeConv("session-1", key));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), makeConv("session-2", key));
    // Re-dispatch the exact same request but against a different session; the
    // saved record belongs to session-1 so it must not come back live.
    const restored = next.drafts.register(next.conv, request);
    await next.drafts.restore(restored);
    expect(snapshots(next.messages).at(-1).fields).toEqual([]);
  });

  it("does not restore live fields when the request id differs", async () => {
    const root = await storage();
    const key = randomUUID();
    const first = controller(new DraftStore(root), makeConv("session-1", key));
    const q = first.drafts.register(first.conv, request);
    await first.drafts.save(payload(q));
    const next = controller(new DraftStore(root), makeConv("session-1", key));
    // Same schema/session/binding, only the request identity changes.
    const other = next.drafts.register(next.conv, { ...request, id: "q2" });
    await next.drafts.restore(other);
    expect(snapshots(next.messages).at(-1).fields).toEqual([]);
  });

  it("does not restore live fields on exact re-dispatch once the session is no longer live", async () => {
    const root = await storage();
    const key = randomUUID();
